# Teste ponta a ponta da API (requer a API rodando em http://127.0.0.1:8090 e o banco recém-criado pelo script).
# Uso: pip install requests && python scripts/teste_e2e.py
import requests, json
B="http://127.0.0.1:8090"
ok=0; bad=0
def check(label, r, exp):
    global ok,bad
    good = r.status_code==exp
    ok+=good; bad+= (not good)
    print(("PASS" if good else "FAIL"), r.status_code, "(esperado %d)"%exp, label, "" if good else r.text[:300])
    return r
def login(e,s):
    r=requests.post(B+"/login",json={"email":e,"senha":s}); return r
def H(t): return {"Authorization":"Bearer "+t}
def idof(r): return int(r.headers["Location"].rstrip("/").split("/")[-1])

